import{_ as a,o as e,c as s,ag as n}from"./chunks/framework.BcZEdlUI.js";const u=JSON.parse('{"title":"第一人称解说生产规范","description":"面向影视/短剧第一人称解说的标准化生产流程、质量门禁与发布参数。","frontmatter":{"title":"第一人称解说生产规范","description":"面向影视/短剧第一人称解说的标准化生产流程、质量门禁与发布参数。"},"headers":[],"relativePath":"guide/first-person-narration-production.md","filePath":"guide/first-person-narration-production.md","lastUpdated":1781612925000}'),d={name:"guide/first-person-narration-production.md"};function r(l,t,i,p,o,h){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="第一人称解说生产规范" tabindex="-1">第一人称解说生产规范 <a class="header-anchor" href="#第一人称解说生产规范" aria-label="Permalink to &quot;第一人称解说生产规范&quot;">​</a></h1><p>本文档把公开平台规则、短视频制作规律和本项目工程约束合并为一套可执行流程。目标是让素材采集、脚本、配音、字幕、导出和发布都有统一标准。</p><h2 id="调研结论" tabindex="-1">调研结论 <a class="header-anchor" href="#调研结论" aria-label="Permalink to &quot;调研结论&quot;">​</a></h2><p>参考资料：</p><ul><li>MCP 抓取样本：<a href="https://www.hongguoduanju.com/" target="_blank" rel="noreferrer">红果短剧官网</a> — 热门短剧集中使用“女性成长、都市爱情、打脸虐渣、穿越、逆袭、马甲、家庭伦理、甜宠、重生、闪婚、战神归来”等高识别度标签。</li><li>MCP 抓取样本：<a href="https://blog.youtube/topic-hub/shorts/" target="_blank" rel="noreferrer">YouTube Shorts Topic Hub</a> — Shorts 是独立的短视频创作与分发场景，需要把竖屏、快节奏和创作者工具作为一等约束。</li><li>YouTube Help: <a href="https://support.google.com/youtube/answer/10059070?hl=en" target="_blank" rel="noreferrer">Get started creating YouTube Shorts</a></li><li>YouTube Help: <a href="https://support.google.com/youtube/answer/15424877?hl=en" target="_blank" rel="noreferrer">Understand three-minute YouTube Shorts</a></li><li>Qt 6: <a href="https://doc.qt.io/qt-6/stylesheet-reference.html" target="_blank" rel="noreferrer">Qt Style Sheets Reference</a></li></ul><p>核心原则：</p><ol><li>短视频优先竖屏交付，默认画布为 1080x1920。</li><li>YouTube Shorts 已支持最长 3 分钟，脚本系统不能只按 60 秒模型估算字数。</li><li>第一人称解说要用“我”的视角推动情绪和动机，不能只复述画面。</li><li>短剧解说必须把题材标签、人物关系、冲突桥段和爽点作为结构化输入。</li><li>字幕是移动端核心信息载体，必须和配音节奏一起设计。</li><li>UI 主题必须使用 Qt QSS 支持的属性和值，避免 Web CSS 写法。</li></ol><h2 id="短剧解说内容模型" tabindex="-1">短剧解说内容模型 <a class="header-anchor" href="#短剧解说内容模型" aria-label="Permalink to &quot;短剧解说内容模型&quot;">​</a></h2><p>短剧与电影解说最大的差异不是时长，而是“连续钩子密度”。公开短剧平台样本显示，热门内容通常直接暴露题材和情绪标签，生产系统也应把这些标签结构化，而不是只保存文件名。</p><table tabindex="0"><thead><tr><th>结构字段</th><th>示例</th><th>用途</th></tr></thead><tbody><tr><td>题材</td><td>都市爱情 / 女性成长 / 家庭伦理 / 民国爱情 / 古风权谋</td><td>决定叙述语气和平台标签</td></tr><tr><td>爽点</td><td>打脸虐渣 / 逆袭 / 马甲 / 战神归来 / 追妻火葬场</td><td>决定 Hook 和高潮排序</td></tr><tr><td>人物关系</td><td>真千金-假千金 / 总裁-灰姑娘 / 婆媳 / 继母继姐</td><td>防止脚本前后矛盾</td></tr><tr><td>关键秘密</td><td>身世、婚约、怀孕、隐藏身份、系统能力</td><td>生成悬念和结尾钩子</td></tr><tr><td>集数上下文</td><td>第 N 集、上一集结尾、下一集预告</td><td>避免重复解释和断裂叙事</td></tr></tbody></table><p>桥段识别优先级：</p><ol><li>身份揭露：谁其实是谁，谁隐瞒了什么。</li><li>对峙冲突：主角与反派/家人/恋人正面交锋。</li><li>打脸反转：前文羞辱在当前片段得到回击。</li><li>救场：关键人物、证据或能力突然出现。</li><li>背叛：信任关系破裂，推动情绪下坠。</li><li>心动：关系升温，适合甜宠/爱情线。</li><li>结尾悬念：下一集必须点击的未解决问题。</li></ol><h2 id="标准工作流" tabindex="-1">标准工作流 <a class="header-anchor" href="#标准工作流" aria-label="Permalink to &quot;标准工作流&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>素材导入</span></span>
<span class="line"><span>  -&gt; 版权/来源标注</span></span>
<span class="line"><span>  -&gt; 题材/爽点/人物关系标注</span></span>
<span class="line"><span>  -&gt; 场景拆分</span></span>
<span class="line"><span>  -&gt; 人物与关系抽取</span></span>
<span class="line"><span>  -&gt; 短剧桥段识别</span></span>
<span class="line"><span>  -&gt; 第一人称脚本生成</span></span>
<span class="line"><span>  -&gt; 配音与字幕对齐</span></span>
<span class="line"><span>  -&gt; 竖屏重构与安全区检查</span></span>
<span class="line"><span>  -&gt; 平台导出</span></span>
<span class="line"><span>  -&gt; 发布复盘</span></span></code></pre></div><h2 id="脚本标准" tabindex="-1">脚本标准 <a class="header-anchor" href="#脚本标准" aria-label="Permalink to &quot;脚本标准&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>标准</th></tr></thead><tbody><tr><td>视角</td><td>默认第一人称，“我”是画面内角色或明确的代入叙述者</td></tr><tr><td>开头</td><td>前 3 秒必须给出冲突、身份、危险、目标或反转</td></tr><tr><td>信息密度</td><td>每 6-10 秒推进一次新信息，避免解释同一件事</td></tr><tr><td>句式</td><td>短句优先，保留口语停顿，避免书面总结腔</td></tr><tr><td>情绪</td><td>每段标注情绪强度，配音和字幕共用同一情绪标签</td></tr><tr><td>结尾</td><td>给出反转、悬念、后果或下一集钩子</td></tr></tbody></table><p>短剧脚本结构：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hook: 我以为自己只是被赶出家门，直到那份亲子鉴定摔在所有人面前。</span></span>
<span class="line"><span>关系: 我 / 养父母 / 假千金 / 真正支持我的人</span></span>
<span class="line"><span>冲突: 被羞辱、被误认、被迫离开</span></span>
<span class="line"><span>反击: 证据出现、身份揭露、反派失控</span></span>
<span class="line"><span>收束: 这一刻他们才知道，真正该走的人不是我。</span></span>
<span class="line"><span>下一集钩子: 可那个一直沉默的男人，竟然叫出了我的真名。</span></span></code></pre></div><p>推荐时长与字数：</p><table tabindex="0"><thead><tr><th>成片时长</th><th>适用场景</th><th>中文解说稿参考</th></tr></thead><tbody><tr><td>30-45 秒</td><td>单冲突、单反转</td><td>120-180 字</td></tr><tr><td>60-90 秒</td><td>短剧单桥段</td><td>240-360 字</td></tr><tr><td>120-180 秒</td><td>多桥段串联 / Shorts 长版</td><td>480-720 字</td></tr></tbody></table><h2 id="视频交付标准" tabindex="-1">视频交付标准 <a class="header-anchor" href="#视频交付标准" aria-label="Permalink to &quot;视频交付标准&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台类型</th><th>画布</th><th>字幕安全区</th><th>推荐码率</th></tr></thead><tbody><tr><td>抖音 / TikTok / Shorts / Reels</td><td>1080x1920</td><td>上下各保留 12%，右侧保留互动栏</td><td>8-12 Mbps</td></tr><tr><td>B 站竖屏 / 小红书视频</td><td>1080x1920</td><td>底部保留标题与进度区</td><td>8-12 Mbps</td></tr><tr><td>横屏补档</td><td>1920x1080</td><td>下方字幕 8-12% 区域</td><td>12-20 Mbps</td></tr></tbody></table><p>导出门禁：</p><ul><li>字幕不能为空，且单条字幕不超过两行。</li><li>字幕与配音偏差目标小于 50ms。</li><li>首屏 3 秒内必须出现人物、冲突或结果预告。</li><li>短剧成片必须至少命中一个桥段标签，并在结尾保留悬念或后果。</li><li>成片 loudness 不应忽高忽低，配音必须压过原声。</li></ul>`,24)])])}const b=a(d,[["render",r]]);export{u as __pageData,b as default};
